"          ${posSettings.printLoyaltyPoints && customerPhone && (posSettings.loyaltyPrintOption === 'all' || posSettings.loyaltyPrintOption === 'saved') ? (() => {
            const cust = customerDb[customerPhone] || { points: 0 };
            const redeemed = order.points_redeemed || 0;
            const isSettled = order.status === 'COMPLETED';
            const earnedPoints = pointsEarnedOnBill;
            const finalBalance = isSettled ? cust.points : Math.max(0, cust.points + earnedPoints - redeemed);

            return `
              <div class="dashed-line"></div>
              <div class="center bold" style="font-size: 10px; margin-top: 1mm; text-decoration: underline;">
                LOYALTY REWARDS SUMMARY
              </div>
              <div style="font-size: 10px; margin-top: 1.5mm; display: flex; flex-direction: column; gap: 0.5mm;">
                <div style="display: flex; justify-content: space-between;">
                  <span>Points Earned this Visit:</span>
                  <span class="bold">+${earnedPoints} Pts</span>
                </div>
                ${redeemed > 0 ? `
                <div style="display: flex; justify-content: space-between;">
                  <span>Points Redeemed:</span>
                  <span class="bold">-${redeemed} Pts</span>
                </div>
                ` : ''}
                <div style="display: flex; justify-content: space-between; font-weight: bold; border-top: 1px dashed #000; padding-top: 0.5mm; margin-top: 0.5mm;">
                  <span>Total Accumulated Balance:</span>
                  <span>${finalBalance} Pts</span>
                </div>
              </div>
            `;
          })() : ''}

          <div class="dashed-line"></div>

          <div class="center footer-version">${posSettings.appVersion || 'SaSLoop POS Version: 19.02'}</div>"
